    assert!(bundle.status.success(), "{}", stderr(&bundle));
    let bundle_json: serde_json::Value = serde_json::from_str(&stdout(&bundle)).unwrap();
    let summary_path = Path::new(bundle_json["summary_path"].as_str().unwrap());
