fn create_signed_workbench_support_bundle_with_failed_job(
    base: &Path,
    name: &str,
) -> (PathBuf, PathBuf) {
    let repo = base.join(format!("{name}-repo"));
    copy_fixture(Path::new("../../fixtures/discount-service"), &repo);
    let signing_key = base.join(format!("{name}-support-signing-key.pem"));
    let missing_prompt = base.join(format!("{name}-missing-prompt.sh"));
    generate_native_signing_key(&signing_key, 2048);
    let mut child = Command::new(env!("CARGO_BIN_EXE_ao2"))
        .args([
            "workbench",
            "serve",
            "--target",
            repo.to_str().unwrap(),
            "--port",
            "0",
            "--api-token",
            "test-token",
            "--enable-execution",
            "--support-signing-key",
            signing_key.to_str().unwrap(),
            "--support-signer-id",
            "diagnostics-lead",
        ])
        .env_remove("OPENAI_API_KEY")
        .env_remove("ANTHROPIC_API_KEY")
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    let port = read_server_port(&mut child);
    start_queue_job(port, &format!("{name}-failed"), &missing_prompt);
    wait_for_queue_job_status(port, &format!("{name}-failed"), "failed");
    let export_response = http_request(
        port,
        "POST /api/queue/export?token=test-token HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
    );
    assert!(export_response.starts_with("HTTP/1.1 200 OK"));
    let export: serde_json::Value = serde_json::from_str(http_body(&export_response)).unwrap();
    let bundle_path = PathBuf::from(export["bundle_path"].as_str().unwrap());
    let bundle_dir = bundle_path.parent().unwrap().to_path_buf();
    let _ = child.kill();
    let _ = child.wait();
    (repo, bundle_dir)
}

fn create_signed_workbench_support_bundle_fixture(
    base: &Path,
    name: &str,
    signer_id: &str,
    export_evidence: bool,
) -> (PathBuf, PathBuf) {
    let repo = base.join(format!("{name}-repo"));
    copy_fixture(Path::new("../../fixtures/discount-service"), &repo);
    let signing_key = base.join(format!("{name}-support-signing-key.pem"));
    let prompt_path = base.join(format!("{name}-prompt.sh"));
    generate_native_signing_key(&signing_key, 2048);
    fs::write(
        &prompt_path,
        r#"cat > discount_service/discounts.py <<'PY'
def calculate_discount(price: float, discount_rate: float) -> float:
    if price < 0:
        raise ValueError("price must be non-negative")
    if discount_rate < 0 or discount_rate > 1:
        raise ValueError("discount_rate must be between 0 and 1")
    return price * (1 - discount_rate)
PY
printf 'Summary: signed workbench support bundle fixture\n'
printf 'Changed files: discount_service/discounts.py\n'
"#,
    )
    .unwrap();
    let mut child = Command::new(env!("CARGO_BIN_EXE_ao2"))
        .args([
            "workbench",
            "serve",
            "--target",
            repo.to_str().unwrap(),
            "--port",
            "0",
            "--api-token",
            "test-token",
            "--enable-execution",
            "--support-signing-key",
            signing_key.to_str().unwrap(),
            "--support-signer-id",
            signer_id,
        ])
        .env_remove("OPENAI_API_KEY")
        .env_remove("ANTHROPIC_API_KEY")
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    let port = read_server_port(&mut child);
    start_queue_job(port, &format!("{name}-run"), &prompt_path);
    wait_for_queue_job_status(port, &format!("{name}-run"), "accepted");
    if export_evidence {
        let evidence_body = format!("kind=summary&run_id={name}-run");
        let evidence_request = format!(
            "POST /api/runs/evidence/export?token=test-token HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            evidence_body.len(),
            evidence_body
        );
        let evidence_response = http_request(port, &evidence_request);
        assert!(
            evidence_response.starts_with("HTTP/1.1 200 OK"),
            "{evidence_response}"
        );
    }
    let export_response = http_request(
        port,
        "POST /api/queue/export?token=test-token HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
    );
    assert!(export_response.starts_with("HTTP/1.1 200 OK"));
    let export: serde_json::Value = serde_json::from_str(http_body(&export_response)).unwrap();
    let bundle_path = PathBuf::from(export["bundle_path"].as_str().unwrap());
    let bundle_dir = bundle_path.parent().unwrap().to_path_buf();
    let _ = child.kill();
    let _ = child.wait();
    (repo, bundle_dir)
}

fn tamper_json_file(path: &Path, update: impl FnOnce(&mut serde_json::Value)) {
    let mut value: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(path).unwrap()).unwrap();
    update(&mut value);
    fs::write(path, serde_json::to_string_pretty(&value).unwrap()).unwrap();
}

fn tamper_support_metadata_and_refresh_manifest(stage_dir: &Path, signer_id: &str) {
    let metadata_path = stage_dir.join("support-bundle-metadata.json");
    let mut metadata: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(&metadata_path).unwrap()).unwrap();
    metadata["signer_id"] = serde_json::json!(signer_id);
    fs::write(
        &metadata_path,
        serde_json::to_string_pretty(&metadata).unwrap(),
    )
    .unwrap();
    refresh_sha256sum_entry(stage_dir, "support-bundle-metadata.json");
}

fn refresh_sha256sum_entry(stage_dir: &Path, relative_path: &str) {
    let manifest_path = stage_dir.join("SHA256SUMS");
    let replacement = sha256_hex_for_test(&fs::read(stage_dir.join(relative_path)).unwrap());
    let manifest = fs::read_to_string(&manifest_path).unwrap();
    let updated = manifest
        .lines()
        .map(|line| {
            let mut parts = line.split_whitespace();
            let _digest = parts.next().unwrap_or_default();
            let path = parts.next().unwrap_or_default();
            if path == relative_path {
                format!("{replacement}  {relative_path}")
            } else {
                line.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n");
    fs::write(manifest_path, format!("{updated}\n")).unwrap();
}

fn sha256_hex_for_test(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

fn canonical_sha256_for_test(value: &serde_json::Value) -> String {
    fn write_value(out: &mut String, value: &serde_json::Value) {
        match value {
            serde_json::Value::Null => out.push_str("null"),
            serde_json::Value::Bool(value) => {
                out.push_str(if *value { "true" } else { "false" });
            }
            serde_json::Value::Number(value) => out.push_str(&value.to_string()),
            serde_json::Value::String(value) => write_string(out, value),
            serde_json::Value::Array(values) => {
                out.push('[');
                for (index, item) in values.iter().enumerate() {
                    if index > 0 {
                        out.push(',');
                    }
                    write_value(out, item);
                }
                out.push(']');
            }
            serde_json::Value::Object(map) => {
                let mut keys: Vec<&String> = map.keys().collect();
                keys.sort();
                out.push('{');
                for (index, key) in keys.iter().enumerate() {
                    if index > 0 {
                        out.push(',');
                    }
                    write_string(out, key);
                    out.push(':');
                    write_value(out, &map[*key]);
                }
                out.push('}');
            }
        }
    }
    fn write_string(out: &mut String, value: &str) {
        out.push('"');
        for ch in value.chars() {
            match ch {
                '"' => out.push_str("\\\""),
                '\\' => out.push_str("\\\\"),
                '\n' => out.push_str("\\n"),
                '\r' => out.push_str("\\r"),
                '\t' => out.push_str("\\t"),
                '\u{08}' => out.push_str("\\b"),
                '\u{0c}' => out.push_str("\\f"),
                ch if (ch as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", ch as u32)),
                ch => out.push(ch),
            }
        }
        out.push('"');
    }
    let mut canonical = String::new();
    write_value(&mut canonical, value);
    sha256_hex_for_test(canonical.as_bytes())
}

#[test]
fn cli_control_plane_sources_save_and_refresh_from_source_list() {
    let temp = tempfile::tempdir().unwrap();
    let repo_a = temp.path().join("sources-service-a");
    let repo_b = temp.path().join("sources-service-b");
    copy_fixture(Path::new("../../fixtures/discount-service"), &repo_a);
    copy_fixture(Path::new("../../fixtures/discount-service"), &repo_b);

    for (repo, run_id) in [(&repo_a, "fleet-sources-a"), (&repo_b, "fleet-sources-b")] {
        let run = ao2([
            "run",
            "../../examples/risky-pr-run/risky-pr.yaml",
            "--target",
            repo.to_str().unwrap(),
            "--run-id",
            run_id,
        ]);
        assert!(run.status.success(), "{}", stderr(&run));
    }

    let sources_path = temp.path().join("fleet-sources.json");
    let save = ao2([
        "control-plane",
        "sources",
        "save",
        "--target",
        repo_a.to_str().unwrap(),
        "--target",
        repo_b.to_str().unwrap(),
        "--out",
        sources_path.to_str().unwrap(),
        "--json",
    ]);
    assert!(save.status.success(), "{}", stderr(&save));
    let save_json: serde_json::Value = serde_json::from_str(&stdout(&save)).unwrap();
    assert_eq!(save_json["schema_version"], "ao2.control-plane-sources.v1");
    assert_eq!(save_json["target_count"], 2);
    assert!(sources_path.is_file());

    let fleet_path = temp.path().join("fleet-from-sources.json");
    let refresh = ao2([
        "control-plane",
        "refresh",
        "--sources",
        sources_path.to_str().unwrap(),
        "--out",
        fleet_path.to_str().unwrap(),
        "--json",
    ]);
    assert!(refresh.status.success(), "{}", stderr(&refresh));
    let fleet: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(&fleet_path).unwrap()).unwrap();
    assert_eq!(
        fleet["schema_version"],
        "ao2.control-plane-fleet-snapshot.v1"
    );
    assert_eq!(fleet["repositories"].as_array().unwrap().len(), 2);
    let fleet_text = serde_json::to_string(&fleet).unwrap();
    assert!(fleet_text.contains("fleet-sources-a"));
    assert!(fleet_text.contains("fleet-sources-b"));
}

