#[test]
fn cli_release_support_bundle_verify_rejects_secret_markers() {
    let temp = tempfile::tempdir().unwrap();
    let bundle_path = temp.path().join("release-support-bundle.json");
    write_minimal_release_support_bundle(
        &bundle_path,
        serde_json::json!({
            "operator_log": "Authorization: Bearer should-not-ship",
            "nested": {"access_token": "should-not-ship"}
        }),
    );

    let verify = ao2([
        "release",
        "support-bundle-verify",
        "--bundle",
        bundle_path.to_str().unwrap(),
        "--json",
    ]);
    assert!(
        !verify.status.success(),
        "support verifier should fail on secret markers"
    );
    let json: serde_json::Value = serde_json::from_str(&stdout(&verify)).unwrap();
    assert_eq!(json["status"], "failed");
    let failures = json["failures"].as_array().unwrap();
    assert!(failures
        .iter()
        .any(|failure| failure["code"] == "forbidden_secret_marker"));
    assert!(failures
        .iter()
        .any(|failure| failure["code"] == "forbidden_secret_field"));
    assert!(stderr(&verify).contains("release support bundle verification failed"));
}

fn write_minimal_release_support_bundle(path: &Path, extra: serde_json::Value) {
    let mut bundle = serde_json::json!({
        "schema_version": "ao2.cp-release-support-bundle.v1",
        "release_assembly": {"schema_version": "ao2.cp-release-assembly.v1", "status": "assembled"},
        "readiness": {"schema_version": "ao2.cp-release-readiness.v1", "status": "ready"},
        "handoff": {"schema_version": "factory-v3/ao2-release-handoff-checklist/v1", "status": "ready_for_evaluator_closer"},
        "cockpit": {"schema_version": "ao2.cp-release-cockpit.v1", "status": "ready"},
        "evaluator_decision": {"schema_version": "factory-v3/ao2-release-evaluator-decision/v1", "decision": "accept_phase1_release_candidate"},
        "storage_support": {"schema_version": "ao2.cp-storage-support.v1", "status": "ready"}
    });
    if !extra.is_null() {
        bundle["diagnostics"] = extra;
    }
    fs::write(path, serde_json::to_string_pretty(&bundle).unwrap()).unwrap();
}

fn sha256_path(path: &Path) -> String {
    let body = fs::read(path).unwrap();
    let mut hasher = Sha256::new();
    hasher.update(body);
    format!("{:x}", hasher.finalize())
}

fn archive_entries(path: &Path) -> Vec<String> {
    let archive = fs::File::open(path).expect("open archive");
    let decoder = GzDecoder::new(archive);
    let mut archive = Archive::new(decoder);
    let mut entries = archive
        .entries()
        .expect("archive entries")
        .map(|entry| {
            entry
                .expect("archive entry")
                .path()
                .expect("entry path")
                .to_string_lossy()
                .trim_start_matches("./")
                .to_string()
        })
        .collect::<Vec<_>>();
    entries.sort();
    entries
}

fn archive_text_entry(path: &Path, wanted: &str) -> String {
    let archive = fs::File::open(path).expect("open archive");
    let decoder = GzDecoder::new(archive);
    let mut archive = Archive::new(decoder);
    for entry in archive.entries().expect("archive entries") {
        let mut entry = entry.expect("archive entry");
        let path = entry
            .path()
            .expect("entry path")
            .to_string_lossy()
            .trim_start_matches("./")
            .to_string();
        if path == wanted {
            let mut body = String::new();
            entry.read_to_string(&mut body).expect("read archive text");
            return body;
        }
    }
    panic!("missing archive entry {wanted}");
}

fn ao2<const N: usize>(args: [&str; N]) -> std::process::Output {
    let mut command = Command::new(env!("CARGO_BIN_EXE_ao2"));
    command.args(args);
    command.env_remove("OPENAI_API_KEY");
    command.env_remove("ANTHROPIC_API_KEY");
    command.output().unwrap()
}

fn sh_command() -> PathBuf {
    ao2_adapters::posix_shell_command().unwrap_or_else(|| PathBuf::from("sh"))
}

fn normalize_separators(input: &str) -> String {
    input.replace('\\', "/")
}

fn generate_native_signing_key(path: &Path, bits: usize) {
    let output = Command::new(env!("CARGO_BIN_EXE_ao2"))
        .args(["workbench", "support-keygen", "--out"])
        .arg(path)
        .args(["--bits", &bits.to_string()])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "stdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        path.is_file(),
        "native signing key exists: {}",
        path.display()
    );
}

